---
import { Button } from "@/components/ui/button"
import { Toaster } from "@/components/ui/toast"
---

<div data-toast-demo>
  <Button variant="outline" data-show-toast>
    Show Toast
  </Button>
  <Toaster portal />
</div>

<script>
  const initialize = () => {
    for (const root of document.querySelectorAll("[data-toast-demo]")) {
      if (root.hasAttribute("data-bound")) continue
      root.setAttribute("data-bound", "")
      const toaster = root.querySelector('[data-slot="toast"]')
      root.querySelector("[data-show-toast]")?.addEventListener("click", () => {
        // The action closes its toast, like toast.close(id) in the React example.
        toaster?.dispatchEvent(
          new CustomEvent("toast:show", {
            detail: {
              title: "Event created",
              description: "Sunday, December 3 at 9:00 AM",
              action: { label: "Undo", value: "undo" },
            },
          })
        )
      })
    }
  }

  initialize()
  document.addEventListener("astro:page-load", initialize)
</script>

---
import { Button } from "@/components/ui/button"
import { Toaster } from "@/components/ui/toast"
---

<div data-toast-promise>
  <Button variant="outline" data-create-event>
    Create Event
  </Button>
  <Toaster portal />
</div>

<script>
  const initialize = () => {
    for (const root of document.querySelectorAll("[data-toast-promise]")) {
      if (root.hasAttribute("data-bound")) continue
      root.setAttribute("data-bound", "")
      const toaster = root.querySelector('[data-slot="toast"]')
      const send = (name: string, detail: object) =>
        toaster?.dispatchEvent(new CustomEvent(name, { detail }))
      root
        .querySelector("[data-create-event]")
        ?.addEventListener("click", async () => {
          // One toast moves from loading to success or error.
          const id = `event-${Date.now()}`
          send("toast:show", {
            id,
            title: "Creating event…",
            type: "loading",
            duration: 0,
          })
          try {
            const data = await new Promise<{ name: string }>((resolve) => {
              window.setTimeout(() => resolve({ name: "Event" }), 2000)
            })
            send("toast:update", {
              id,
              title: `${data.name} created.`,
              type: "success",
              duration: 5000,
            })
          } catch {
            send("toast:update", {
              id,
              title: "Could not create event.",
              type: "error",
              duration: 5000,
            })
          }
        })
    }
  }

  initialize()
  document.addEventListener("astro:page-load", initialize)
</script>

---
import { Button } from "@/components/ui/button"
import { Toaster } from "@/components/ui/toast"

const toasts = [
  { label: "Default", description: "Event has been created." },
  {
    label: "Success",
    type: "success",
    description: "Event has been created.",
  },
  {
    label: "Info",
    type: "info",
    description: "Arrive 10 minutes before the event.",
  },
  {
    label: "Warning",
    type: "warning",
    description: "The event cannot start before 8:00 AM.",
  },
  {
    label: "Error",
    type: "error",
    description: "The event could not be created.",
  },
]
---

<div class="flex flex-wrap gap-2" data-toast-types>
  {toasts.map((toast) => (
    <Button
      variant="outline"
      data-toast-type={toast.type}
      data-toast-description={toast.description}
    >
      {toast.label}
    </Button>
  ))}
  <Toaster portal />
</div>

<script>
  const initialize = () => {
    for (const root of document.querySelectorAll("[data-toast-types]")) {
      if (root.hasAttribute("data-bound")) continue
      root.setAttribute("data-bound", "")
      const toaster = root.querySelector('[data-slot="toast"]')
      for (const button of root.querySelectorAll<HTMLElement>(
        "[data-toast-description]"
      )) {
        button.addEventListener("click", () => {
          const { toastType, toastDescription } = button.dataset
          // A toast needs a title, so the text shows as the title.
          toaster?.dispatchEvent(
            new CustomEvent("toast:show", {
              detail: { title: toastDescription, type: toastType },
            })
          )
        })
      }
    }
  }

  initialize()
  document.addEventListener("astro:page-load", initialize)
</script>
